  --color-m-light: #81c4ff;
  --color-m-dark: #16588e;
  --color-m-red: #e7222e;

  --color-brand: #16588e; /* accent for text, borders, focus rings: M dark blue */
  --color-brand-fill: #16588e; /* filled controls with white content (primary button, toggle) */
  --color-brand-soft: #e6f0f9;
  --color-canvas: #f2f3f4; /* app background behind the panels */
  --color-dot: #d2d5d9; /* dot grid on the canvas */
