  --color-muted: #5d636b;
  --color-danger: #c81e28; /* M red, a shade darker so small text stays readable */
  --color-danger-soft: #fdecec;
  --color-warn: #a35f00;
  --color-warn-soft: #fff4e0;
  --color-ok: #1b7f4b;

  /* Block groups (see BlockGroup in @reqflow/core), drawn from the M stripe */
  --color-group-structure: #6b7078;
  --color-group-source: #2b8ee6; /* M light blue, deepened for white backgrounds */
  --color-group-ai: #16588e; /* M dark blue */
  --color-group-human: #e7222e; /* M red: a person has to act here */
  --color-group-output: #111214; /* the car itself */
}

