import * as THREE from "three";

/**
 * The car body as one smooth parametric surface, cut into panels.
 *
 * Built procedurally (no downloaded model) from the published outer dimensions of the BMW 5 Series
 * Sedan (G60): length 5,060 mm, width 1,900 mm, height 1,515 mm, wheelbase 2,995 mm. The shapes in
 * between (roof line, tumblehome, overhangs) are drawn to match its side view, not measured.
 *
 * Axes: x forward (front bumper at +2.53), y up (ground at 0), z to the car's right; metres.
 * The surface is a tube: one cross-section ring per station along x. Each ring runs through ten
 * control points per side (bottom → sill → side → shoulder → belt → glass → roof). Every quad of
 * the grid is then given to one panel (hood, front door, windscreen, …) by where it sits, so the
 * panels share vertices and normals and the car shades as one smooth surface.
 */

export const G60 = {
  length: 5.06,
  width: 1.9,
  height: 1.515,
  wheelbase: 2.995,
  frontAxleX: 1.58,
  rearAxleX: -1.415,
  track: 1.63,
  tyreRadius: 0.37,
  tyreWidth: 0.245,
  rimRadius: 0.245,
  archRadius: 0.425,
} as const;

const HALF_L = G60.length / 2;

type Pt = readonly [number, number];

/** Smooth curve y(x) through key points (cubic Hermite, Catmull-Rom tangents), clamped at the ends. */
export function profile(points: readonly Pt[]): (x: number) => number {
  const p = [...points].sort((a, b) => a[0] - b[0]);
  const last = p.length - 1;
  return (x) => {
    if (x <= p[0]![0]) return p[0]![1];
    if (x >= p[last]![0]) return p[last]![1];
    let i = 0;
    while (x > p[i + 1]![0]) i++;
    const p0 = p[Math.max(0, i - 1)]!;
    const p1 = p[i]!;
    const p2 = p[i + 1]!;
    const p3 = p[Math.min(last, i + 2)]!;
    const dx = p2[0] - p1[0];
    const t = (x - p1[0]) / dx;
    const m1 = ((p2[1] - p0[1]) / (p2[0] - p0[0])) * dx;
    const m2 = ((p3[1] - p1[1]) / (p3[0] - p1[0])) * dx;
    const t2 = t * t;
    const t3 = t2 * t;
    return (
      (2 * t3 - 3 * t2 + 1) * p1[1] +
      (t3 - 2 * t2 + t) * m1 +
      (-2 * t3 + 3 * t2) * p2[1] +
      (t3 - t2) * m2
    );
  };
}

const smoothstep = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

/** Side view: the top line (bumper → bonnet → windscreen → roof → rear window → boot → bumper). */
export const topLine = profile([
  [2.53, 0.62],
  [2.5, 0.74],
  [2.43, 0.82],
  [2.25, 0.87],
  [1.6, 0.935],
  [1.05, 0.98],
  [0.82, 0.995],
  [0.55, 1.13],
  [0.25, 1.31],
  [0.0, 1.43],
  [-0.3, 1.495],
  [-0.7, 1.515],
  [-1.1, 1.485],
  [-1.45, 1.38],
  [-1.75, 1.21],
  [-1.97, 1.105],
  [-2.2, 1.09],
  [-2.36, 1.098],
  [-2.47, 1.04],
  [-2.53, 0.93],
]);

/** Window line (the lower edge of the side glass); rises slightly to the rear. */
export const beltLine = profile([
  [0.9, 0.975],
  [0.0, 0.99],
  [-1.0, 1.015],
  [-1.6, 1.05],
  [-1.95, 1.085],
  [-2.15, 1.11],
]);

/** Side view: the bottom line (front apron → sills → rear apron). */
export const bottomLine = profile([
  [2.53, 0.36],
  [2.38, 0.25],
  [2.0, 0.2],
  [1.0, 0.165],
  [-1.0, 0.165],
  [-2.0, 0.22],
  [-2.4, 0.3],
  [-2.53, 0.42],
]);

const baseHalfWidth = profile([
  [-2.53, 0.915],
  [-2.0, 0.935],
  [-1.4, 0.95],
  [0, 0.95],
  [1.6, 0.945],
  [2.2, 0.92],
  [2.53, 0.9],
]);

const NOSE_START = 2.1;
const TAIL_START = -2.16;

/** Plan view: half the body width; the ends round off like a superellipse. */
export function halfWidth(x: number): number {
  let w = baseHalfWidth(x);
  const e = 3.2;
  if (x > NOSE_START) {
    const s = Math.min(1, (x - NOSE_START) / (HALF_L - NOSE_START));
    w *= Math.pow(Math.max(0, 1 - Math.pow(s, e)), 1 / e);
  }
  if (x < TAIL_START) {
    const s = Math.min(1, (TAIL_START - x) / (TAIL_START + HALF_L));
    w *= Math.pow(Math.max(0, 1 - Math.pow(s, e)), 1 / e);
  }
  return w;
}

/** Samples per segment of the cross-section and number of segments per side. */
const PER_SEG = 8;
const HALF_SEGS = 9;
/** Ring points: both sides, closed loop (bottom centre and top centre shared). */
export const RING = PER_SEG * HALF_SEGS * 2;
export const STATIONS = 170;

/**
 * Segment of the cross-section a ring index belongs to, counted on one side from the bottom:
 * 0 floor · 1 sill · 2 lower side · 3 upper side · 4 shoulder → belt · 5–6 side glass · 7–8 roof.
 * Where there is no greenhouse (bonnet, boot) 5–8 are the top of the bonnet or boot lid.
 */
export function segmentOf(ringIndex: number): number {
  const seg = Math.floor(ringIndex / PER_SEG) % (HALF_SEGS * 2);
  return seg < HALF_SEGS ? seg : HALF_SEGS * 2 - 1 - seg;
}

/** Ring index on the right-hand side (z > 0) where segment `seg` starts. */
export const ringIndexOf = (seg: number) => seg * PER_SEG;

interface Section {
  x: number;
  /** 0 = no greenhouse (bonnet, boot) … 1 = full side window. */
  glass: number;
  points: THREE.Vector3[];
}

function section(x: number): Section {
  const w = halfWidth(x);
  const yt = topLine(x);
  const yb = bottomLine(x);
  const ybe = Math.min(beltLine(x), yt - 0.03);
  const h = yt - ybe;
  const g = smoothstep(0.06, 0.3, h);
  const wr = lerp(0.86 * w, Math.min(0.67, 0.86 * w), g);
  // Right-hand side, bottom centre → top centre (z, y).
  const half: Pt[] = [
    [0, yb],
    [0.78 * w, yb],
    [0.965 * w, yb + 0.07],
    [w, yb + 0.55 * (ybe - yb)],
    [0.985 * w, ybe - 0.06],
    [0.95 * w, ybe],
    [lerp(0.95 * w, wr, 0.62), ybe + 0.58 * h],
    [wr, yt - 0.045 * g - 0.012],
    [0.5 * wr, yt - 0.006],
    [0, yt],
  ];
  // Closed loop: right side up, then the left side down (mirrored), without repeating the centres.
  const loop: THREE.Vector3[] = [
    ...half.map(([z, y]) => new THREE.Vector3(x, y, z)),
    ...half
      .slice(1, -1)
      .reverse()
      .map(([z, y]) => new THREE.Vector3(x, y, -z)),
  ];
  const curve = new THREE.CatmullRomCurve3(loop, true, "centripetal");
  const points: THREE.Vector3[] = [];
  for (let i = 0; i < RING; i++) points.push(curve.getPoint(i / RING));
  return { x, glass: g, points };
}

export interface BodyGrid {
  positions: Float32Array;
  normals: Float32Array;
  /** Per station: how much greenhouse it has (0–1). */
  glass: number[];
  stationX: number[];
}

/** Station positions, denser at the ends where the nose and tail curve fast. */
function stationXs(): number[] {
  const xs: number[] = [];
  for (let i = 0; i < STATIONS; i++) {
    const u = i / (STATIONS - 1);
    const s = 0.5 - 0.5 * Math.cos(Math.PI * u); // 0…1, dense at both ends
    const mix = 0.55 * s + 0.45 * u;
    xs.push(-HALF_L + G60.length * mix);
  }
  return xs;
}

export function buildBodyGrid(): BodyGrid {
  const stationX = stationXs();
  const positions = new Float32Array(STATIONS * RING * 3);
  const glass: number[] = [];
  stationX.forEach((x, i) => {
    const s = section(x);
    glass.push(s.glass);
    s.points.forEach((p, j) => {
      const o = (i * RING + j) * 3;
      positions[o] = p.x;
      positions[o + 1] = p.y;
      positions[o + 2] = p.z;
    });
  });
  const all = new THREE.BufferGeometry();
  all.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  all.setIndex(gridIndex(() => true));
  all.computeVertexNormals();
  const normals = all.getAttribute("normal").array as Float32Array;
  return { positions, normals, glass, stationX };
}

export interface Quad {
  i: number;
  j: number;
  /** Centre of the quad. */
  x: number;
  y: number;
  z: number;
  /** Cross-section segment (see segmentOf). */
  seg: number;
  /** Greenhouse amount at this station. */
  glass: number;
  /** Outward normal at the centre. */
  nx: number;
  ny: number;
  nz: number;
}

const vid = (i: number, j: number) => i * RING + (j % RING);

/** Triangle indices of every quad the predicate keeps. Normals face outward. */
function gridIndex(keep: (i: number, j: number) => boolean): number[] {
  const index: number[] = [];
  for (let i = 0; i < STATIONS - 1; i++) {
    for (let j = 0; j < RING; j++) {
      if (!keep(i, j)) continue;
      const a = vid(i, j);
      const b = vid(i + 1, j);
      const c = vid(i + 1, j + 1);
      const d = vid(i, j + 1);
      index.push(a, d, b, b, d, c);
    }
  }
  return index;
}

export function quadAt(grid: BodyGrid, i: number, j: number): Quad {
  const ids = [vid(i, j), vid(i + 1, j), vid(i + 1, j + 1), vid(i, j + 1)];
  let x = 0;
  let y = 0;
  let z = 0;
  let nx = 0;
  let ny = 0;
  let nz = 0;
  for (const v of ids) {
    x += grid.positions[v * 3]!;
    y += grid.positions[v * 3 + 1]!;
    z += grid.positions[v * 3 + 2]!;
    nx += grid.normals[v * 3]!;
    ny += grid.normals[v * 3 + 1]!;
    nz += grid.normals[v * 3 + 2]!;
  }
  const len = Math.hypot(nx, ny, nz) || 1;
  return {
    i,
    j,
    x: x / 4,
    y: y / 4,
    z: z / 4,
    seg: segmentOf(j),
    glass: Math.max(grid.glass[i]!, grid.glass[i + 1]!),
    nx: nx / len,
    ny: ny / len,
    nz: nz / len,
  };
}

/** One geometry per key, sharing the grid's vertices (optionally pushed out along the normals). */
export function panelGeometries(
  grid: BodyGrid,
  assign: (q: Quad) => string | null,
  offset = 0,
): Map<string, THREE.BufferGeometry> {
  const buckets = new Map<string, boolean[]>();
  for (let i = 0; i < STATIONS - 1; i++) {
    for (let j = 0; j < RING; j++) {
      const key = assign(quadAt(grid, i, j));
      if (key === null) continue;
      let mask = buckets.get(key);
      if (!mask) {
        mask = new Array<boolean>(STATIONS * RING).fill(false);
        buckets.set(key, mask);
      }
      mask[i * RING + j] = true;
    }
  }
  let positions = grid.positions;
  if (offset !== 0) {
    positions = new Float32Array(grid.positions.length);
    for (let k = 0; k < positions.length; k++) {
      positions[k] = grid.positions[k]! + grid.normals[k]! * offset;
    }
  }
  const position = new THREE.BufferAttribute(positions, 3);
  const normal = new THREE.BufferAttribute(grid.normals, 3);
  const out = new Map<string, THREE.BufferGeometry>();
  for (const [key, mask] of buckets) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", position);
    geo.setAttribute("normal", normal);
    geo.setIndex(gridIndex((i, j) => mask[i * RING + j]!));
    geo.computeBoundingBox();
    geo.computeBoundingSphere();
    out.set(key, geo);
  }
  return out;
}

/** A line along one ring index (e.g. the shoulder), only where `keep` holds; for sketch lines. */
export function featureLine(
  grid: BodyGrid,
  ringIndex: number,
  keep: (x: number, y: number) => boolean,
): THREE.BufferGeometry {
  const pts: number[] = [];
  for (let i = 0; i < STATIONS - 1; i++) {
    const a = vid(i, ringIndex) * 3;
    const b = vid(i + 1, ringIndex) * 3;
    const p = grid.positions;
    if (!keep(p[a]!, p[a + 1]!) || !keep(p[b]!, p[b + 1]!)) continue;
    pts.push(p[a]!, p[a + 1]!, p[a + 2]!, p[b]!, p[b + 1]!, p[b + 2]!);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.Float32BufferAttribute(pts, 3));
  return geo;
}

/* ------------------------------------------------------------------------------------------ */
/* Which panel a quad belongs to                                                                */
/* ------------------------------------------------------------------------------------------ */

const AXLES = [G60.frontAxleX, G60.rearAxleX];
const WHEEL_Y = G60.tyreRadius;

export function inWheelArch(q: Pick<Quad, "x" | "y" | "z" | "seg">): boolean {
  if (q.seg === 0 && Math.abs(q.z) < 0.55) return false;
  if (q.seg > 4) return false;
  return AXLES.some((ax) => (q.x - ax) ** 2 + (q.y - WHEEL_Y) ** 2 < G60.archRadius ** 2);
}

/** Side window outline: front edge follows the A-pillar, rear edge the C-pillar, gap = B-pillar. */
function inSideWindow(q: Quad): boolean {
  const front = 0.8 - (q.y - 1.0) * 1.82 - 0.13;
  const rear = -1.62 + (q.y - 1.05) * 0.85;
  const bPillar = q.x > -0.31 && q.x < -0.19;
  return q.x < front && q.x > rear && !bPillar && q.seg <= 6 && q.glass > 0.5;
}

/**
 * Panel key for one quad: a part id, optionally with ":glass" for glazing. null = no surface
 * (wheel arch openings).
 */
export function bodyPanel(q: Quad): string | null {
  const az = Math.abs(q.z);
  if (inWheelArch(q)) return null;
  if (q.seg === 0) return "underbody";

  if (q.seg <= 4) {
    if (q.x > 2.03) return "front_bumper";
    if (q.x < -2.03) return q.y < 0.93 ? "rear_bumper" : az < 0.8 ? "trunk_lid" : "body";
    if (q.seg >= 2) {
      if (q.x <= 0.86 && q.x >= -0.22) return "front_doors";
      if (q.x < -0.22 && q.x >= -1.3) return "rear_doors";
    }
    return "body";
  }

  // Top of the car: bonnet, windscreen, roof, rear window, boot lid.
  if (q.x > 0.86) return "hood";
  if (q.x < -1.97) return "trunk_lid";
  if ((q.seg === 5 || q.seg === 6) && inSideWindow(q)) return "side_windows:glass";
  if (q.seg >= 7 || q.glass < 0.5) {
    if (q.x > 0.02) return az < 0.6 && q.glass > 0.15 ? "windshield:glass" : "roof";
    if (q.x < -1.28) return az < 0.6 && q.glass > 0.15 ? "rear_window:glass" : "roof";
    if (az < 0.47 && q.x < -0.18 && q.x > -1.12) return "roof:glass";
  }
  return "roof";
}

/** Small surface details laid on the body: lights, grille, handles, charge flap. */
export function bodyDetail(q: Quad): string | null {
  const az = Math.abs(q.z);
  if (inWheelArch(q)) return null;
  // Kidney grille: two rounded shapes either side of the centre, on the front face.
  if (q.nx > 0.45 && q.x > 2.2) {
    const k = ((az - 0.165) / 0.145) ** 4 + ((q.y - 0.625) / 0.155) ** 4;
    if (k < 1) return "kidney_grille:dark";
    if (q.y > 0.3 && q.y < 0.43 && az < 0.6) return "front_bumper:dark"; // lower air intake
    if (az < 0.07 && q.y > 0.44 && q.y < 0.48) return "driver_assistance:dark"; // radar
  }
  // Headlights: slim, wrapping slightly round the corner.
  if (q.x > 1.98 && q.nx > 0.12 && q.y > 0.745 && q.y < 0.835 - (az - 0.4) * 0.06 && az > 0.4 && az < 0.88)
    return "headlights:lamp";
  // Tail lights: across the boot lid edge and round the corners.
  if (q.x < -1.98 && q.y > 0.95 && q.y < 1.04 && az > 0.42 && (q.nx < -0.2 || az > 0.84))
    return "taillights:tail";
  // Flush door handles (both sides).
  if (q.seg >= 3 && q.seg <= 4 && q.y > 0.9 && q.y < 0.935) {
    if ((q.x > -0.17 && q.x < -0.03) || (q.x > -1.24 && q.x < -1.1)) return "door_handles:chrome";
  }
  // Charge port flap, rear right quarter panel.
  if (q.z > 0 && q.seg >= 3 && q.seg <= 4 && q.x > -1.88 && q.x < -1.72 && q.y > 0.84 && q.y < 0.95)
    return "charging_port:dark";
  return null;
}

import * as THREE from "three";
import { RoundedBoxGeometry } from "three/addons/geometries/RoundedBoxGeometry.js";
import {
  bodyDetail,
  bodyPanel,
  buildBodyGrid,
  featureLine,
  G60,
  ringIndexOf,
  RING,
  topLine,
} from "./body";

/**
 * Assembles the whole car: the body panels from `body.ts`, plus wheels, chassis and interior built
 * from simple solids at G60 positions. Every mesh that belongs to a part carries its part id, so
 * the viewer can pick, highlight and badge it. No textures, no materials with colour here: the
 * viewer styles every piece by its `kind` so the sketch look follows the app theme.
 */

export type PieceKind =
  | "paint"
  | "glass"
  | "dark"
  | "chrome"
  | "lamp"
  | "tail"
  | "tyre"
  | "rim"
  | "metal"
  | "accent"
  | "trim"
  | "seat"
  | "screen"
  | "glow"
  | "volume"
  | "liner";

/** Exterior pieces fade out in the interior view so you can click what is inside. */
export type PieceLayer = "exterior" | "interior";

export interface CarPiece {
  mesh: THREE.Mesh;
  partId: string | null;
  kind: PieceKind;
  layer: PieceLayer;
}

export interface CarModel {
  root: THREE.Group;
  pieces: CarPiece[];
  /** Extra sketch lines (character lines on the body). */
  sketchLines: THREE.BufferGeometry[];
  /** Where each part's badge sits (world space). */
  anchors: Map<string, THREE.Vector3>;
}

const SIDES = [-1, 1] as const; // left (−z, driver in LHD), right (+z)
const DRIVER_Z = -0.38;

export function buildCar(): CarModel {
  const root = new THREE.Group();
  root.name = "BMW 5 Series (G60) sketch";
  const pieces: CarPiece[] = [];

  const add = (
    geometry: THREE.BufferGeometry,
    partId: string | null,
    kind: PieceKind,
    layer: PieceLayer,
    place?: (m: THREE.Mesh) => void,
  ) => {
    const mesh = new THREE.Mesh(geometry);
    mesh.name = partId ?? kind;
    place?.(mesh);
    mesh.userData.partId = partId;
    root.add(mesh);
    pieces.push({ mesh, partId, kind, layer });
    return mesh;
  };
  const box = (
    partId: string | null,
    kind: PieceKind,
    layer: PieceLayer,
    size: [number, number, number],
    pos: [number, number, number],
    opts: { radius?: number; rotZ?: number; rotY?: number; rotX?: number } = {},
  ) => {
    const r = Math.min(opts.radius ?? 0.03, Math.min(...size) / 2 - 0.0005);
    return add(new RoundedBoxGeometry(size[0], size[1], size[2], 3, r), partId, kind, layer, (m) => {
      m.position.set(...pos);
      m.rotation.set(opts.rotX ?? 0, opts.rotY ?? 0, opts.rotZ ?? 0);
    });
  };
  /** Cylinder along z (axis across the car). */
  const disc = (
    partId: string | null,
    kind: PieceKind,
    layer: PieceLayer,
    radius: number,
    depth: number,
    pos: [number, number, number],
    segments = 36,
  ) =>
    add(
      new THREE.CylinderGeometry(radius, radius, depth, segments).rotateX(Math.PI / 2),
      partId,
      kind,
      layer,
      (m) => m.position.set(...pos),
    );

  // ---- Body ------------------------------------------------------------------------------
  const grid = buildBodyGrid();
  for (const [key, geometry] of panelGeometries(grid)) {
    const [panel, finish] = key.split(":") as [string, string | undefined];
    const partId = panel === "underbody" ? "body" : panel;
    add(geometry, partId, finish === "glass" ? "glass" : "paint", "exterior");
  }
  for (const [key, geometry] of detailGeometries(grid)) {
    const [partId, finish] = key.split(":") as [string, PieceKind];
    add(geometry, partId, finish, "exterior");
  }
  const sketchLines = [
    // Shoulder line at door-handle height, and the sill line between the wheels.
    featureLine(grid, ringIndexOf(4), (x) => x < 2.0 && x > -2.0),
    featureLine(grid, RING - ringIndexOf(4), (x) => x < 2.0 && x > -2.0),
    featureLine(grid, ringIndexOf(2), (x) => x < 1.1 && x > -0.95),
    featureLine(grid, RING - ringIndexOf(2), (x) => x < 1.1 && x > -0.95),
  ];

  // Wheel arch liners (not a part; they hide the inside of the body behind the wheels).
  for (const axle of [G60.frontAxleX, G60.rearAxleX]) {
    for (const side of SIDES) {
      add(
        new THREE.CylinderGeometry(0.43, 0.43, 0.3, 32, 1, true, Math.PI / 2, Math.PI).rotateX(
          Math.PI / 2,
        ),
        null,
        "liner",
        "exterior",
        (m) => m.position.set(axle, G60.tyreRadius, side * 0.78),
      );
    }
  }

  // ---- Mirrors, antenna --------------------------------------------------------------------
  for (const side of SIDES) {
    box("mirrors", "paint", "exterior", [0.13, 0.11, 0.22], [0.7, 1.04, side * 1.05], {
      radius: 0.045,
      rotY: side * -0.12,
    });
    box("mirrors", "paint", "exterior", [0.07, 0.03, 0.12], [0.73, 1.0, side * 0.95], {
      radius: 0.012,
    });
    box("mirrors", "dark", "exterior", [0.01, 0.085, 0.18], [0.633, 1.04, side * 1.05], {
      radius: 0.004,
      rotY: side * -0.12,
    });
  }
  {
    const fin = new THREE.Shape();
    fin.moveTo(0.02, 0);
    fin.lineTo(-0.16, 0);
    fin.quadraticCurveTo(-0.15, 0.06, -0.125, 0.066);
    fin.quadraticCurveTo(-0.05, 0.04, 0.02, 0);
    const geo = new THREE.ExtrudeGeometry(fin, {
      depth: 0.04,
      bevelEnabled: true,
      bevelSize: 0.006,
      bevelThickness: 0.006,
      bevelSegments: 2,
    }).translate(0, 0, -0.02);
    add(geo, "antenna", "paint", "exterior", (m) => {
      m.position.set(-1.2, topLine(-1.2) - 0.004, 0);
      m.rotation.z = 0.28;
    });
  }

  // ---- Wheels, brakes, suspension ------------------------------------------------------------
  const tyreProfile = [
    [0.25, -0.105],
    [0.3, -0.118],
    [0.345, -0.121],
    [0.362, -0.113],
    [0.37, -0.09],
    [0.372, 0],
    [0.37, 0.09],
    [0.362, 0.113],
    [0.345, 0.121],
    [0.3, 0.118],
    [0.25, 0.105],
  ].map(([r, y]) => new THREE.Vector2(r, y));
  const halfTrack = G60.track / 2;
  for (const axle of [G60.frontAxleX, G60.rearAxleX]) {
    for (const side of SIDES) {
      const z = side * halfTrack;
      add(new THREE.LatheGeometry(tyreProfile, 56).rotateX(Math.PI / 2), "wheels", "tyre", "exterior", (m) =>
        m.position.set(axle, G60.tyreRadius, z),
      );
      // Rim: barrel, lip, hub and five double spokes on the outer face.
      const face = z + side * 0.085;
      add(
        new THREE.CylinderGeometry(0.235, 0.235, 0.2, 40, 1, true).rotateX(Math.PI / 2),
        "wheels",
        "rim",
        "exterior",
        (m) => m.position.set(axle, G60.tyreRadius, z),
      );
      add(new THREE.TorusGeometry(0.238, 0.01, 8, 48), "wheels", "rim", "exterior", (m) =>
        m.position.set(axle, G60.tyreRadius, face),
      );
      disc("wheels", "rim", "exterior", 0.062, 0.04, [axle, G60.tyreRadius, face - side * 0.01]);
      for (let k = 0; k < 10; k++) {
        const a = (k * Math.PI) / 5 + (k % 2 ? 0.11 : -0.11) + Math.floor(k / 2) * 0;
        box(
          "wheels",
          "rim",
          "exterior",
          [0.19, 0.026, 0.022],
          [
            axle + Math.cos(a) * 0.145,
            G60.tyreRadius + Math.sin(a) * 0.145,
            face - side * 0.012,
          ],
          { radius: 0.008, rotZ: a },
        );
      }
      // Brake disc and caliper (M blue), visible through the spokes.
      disc("brakes", "metal", "exterior", 0.19, 0.028, [axle, G60.tyreRadius, z + side * 0.01], 40);
      box(
        "brakes",
        "accent",
        "exterior",
        [0.1, 0.16, 0.06],
        [axle - 0.13, G60.tyreRadius + 0.1, z + side * 0.03],
        { radius: 0.02, rotZ: 0.9 },
      );
      // Suspension: damper with a coil spring round it, above the wheel centre.
      const damperZ = side * 0.6;
      add(
        new THREE.CylinderGeometry(0.028, 0.028, 0.36, 16),
        "suspension",
        "metal",
        "interior",
        (m) => m.position.set(axle - 0.02, 0.6, damperZ),
      );
      add(new THREE.TubeGeometry(helix(0.065, 0.3, 6), 160, 0.009, 6), "suspension", "accent", "interior", (m) =>
        m.position.set(axle - 0.02, 0.45, damperZ),
      );
      // Lower control arm towards the body.
      box("suspension", "metal", "interior", [0.08, 0.03, 0.42], [axle, 0.33, side * 0.42], {
        radius: 0.012,
      });
    }
  }

  // ---- Drivetrain: battery under the floor, a motor and drive shafts on each axle ----------------
  box("drivetrain", "dark", "interior", [2.5, 0.11, 1.42], [-0.05, 0.255, 0], { radius: 0.03 });
  for (const axle of [G60.frontAxleX, G60.rearAxleX]) {
    disc("drivetrain", "metal", "interior", 0.13, 0.36, [axle, 0.42, 0], 32);
    for (const side of SIDES) {
      add(
        new THREE.CylinderGeometry(0.022, 0.022, 0.52, 10).rotateX(Math.PI / 2),
        "drivetrain",
        "metal",
        "interior",
        (m) => m.position.set(axle, 0.39, side * 0.45),
      );
    }
  }

  // ---- Interior -------------------------------------------------------------------------------
  // Front seats: cushion, backrest leaning back, headrest.
  for (const side of SIDES) {
    const z = side * 0.38;
    box("front_seats", "seat", "interior", [0.54, 0.12, 0.5], [-0.12, 0.47, z], {
      radius: 0.05,
      rotZ: 0.06,
    });
    seatBack("front_seats", -0.43, 0.82, z, 0.5, 0.64, 0.24);
  }
  // Rear seats: three places on one bench.
  for (const [z, w] of [
    [-0.45, 0.44],
    [0, 0.38],
    [0.45, 0.44],
  ] as const) {
    box("rear_seats", "seat", "interior", [0.5, 0.13, w], [-1.02, 0.5, z], {
      radius: 0.05,
      rotZ: 0.05,
    });
    seatBack("rear_seats", -1.33, 0.86, z, w, 0.6, 0.3);
  }

  function seatBack(partId: string, x: number, y: number, z: number, w: number, h: number, lean: number) {
    box(partId, "seat", "interior", [0.13, h, w], [x, y, z], { radius: 0.05, rotZ: lean });
    const d = h / 2 + 0.13;
    box(
      partId,
      "seat",
      "interior",
      [0.1, 0.17, Math.min(0.28, w - 0.1)],
      [x - Math.sin(lean) * d, y + Math.cos(lean) * d, z],
      { radius: 0.04, rotZ: lean },
    );
  }

  // Steering wheel in front of the driver, tilted towards them.
  {
    const wheel = new THREE.Group();
    const parts = [
      new THREE.TorusGeometry(0.185, 0.019, 12, 48),
      new THREE.CylinderGeometry(0.06, 0.07, 0.05, 24).rotateX(Math.PI / 2),
      new THREE.BoxGeometry(0.15, 0.03, 0.02).translate(-0.11, -0.02, 0),
      new THREE.BoxGeometry(0.15, 0.03, 0.02).translate(0.11, -0.02, 0),
      new THREE.BoxGeometry(0.03, 0.13, 0.02).translate(0, -0.11, 0),
    ];
    for (const g of parts) wheel.add(new THREE.Mesh(g));
    wheel.updateMatrixWorld(true);
    const merged = mergeChildren(wheel);
    add(merged, "steering_wheel", "trim", "interior", (m) => {
      m.position.set(0.3, 0.93, DRIVER_Z);
      m.rotation.set(0, -Math.PI / 2, 0, "YXZ");
      m.rotateX(-0.42);
    });
    add(
      new THREE.CylinderGeometry(0.03, 0.035, 0.3, 12),
      "steering_wheel",
      "trim",
      "interior",
      (m) => {
        m.position.set(0.44, 0.88, DRIVER_Z);
        m.rotation.z = Math.PI / 2 - 0.42;
      },
    );
  }

  // Dashboard and the illuminated interaction bar.
  box("dashboard", "trim", "interior", [0.4, 0.24, 1.56], [0.74, 0.84, 0], { radius: 0.08 });
  box("dashboard", "trim", "interior", [0.24, 0.2, 1.48], [0.72, 0.64, 0], { radius: 0.06 });
  box("dashboard", "glow", "interior", [0.012, 0.022, 1.3], [0.535, 0.875, 0.05], {
    radius: 0.005,
  });

  // BMW Curved Display: one curved glass panel from behind the wheel to the middle.
  {
    const R = 0.88;
    const cx = -0.33;
    add(
      new THREE.CylinderGeometry(R, R, 0.13, 48, 1, true, 1.05, 0.94),
      "curved_display",
      "screen",
      "interior",
      (m) => m.position.set(cx, 1.03, DRIVER_Z),
    );
    add(
      new THREE.CylinderGeometry(R + 0.012, R + 0.012, 0.145, 48, 1, true, 1.04, 0.96),
      "curved_display",
      "dark",
      "interior",
      (m) => m.position.set(cx, 1.03, DRIVER_Z),
    );
  }

  // Head-up display: the unit in the dash and its image in the windscreen.
  box("hud", "dark", "interior", [0.2, 0.04, 0.28], [0.72, 0.975, DRIVER_Z], { radius: 0.015 });
  add(new THREE.PlaneGeometry(0.3, 0.085), "hud", "glow", "interior", (m) => {
    m.position.set(0.47, 1.17, DRIVER_Z);
    m.rotation.set(0, -Math.PI / 2, 0, "YXZ");
    m.rotateX(-0.9);
  });

  // Climate: four air vents under the display and the climate control strip.
  for (const z of [-0.66, -0.14, 0.14, 0.66]) {
    box("climate", "dark", "interior", [0.02, 0.045, 0.17], [0.54, 0.905, z], { radius: 0.008 });
  }
  box("climate", "trim", "interior", [0.02, 0.045, 0.34], [0.54, 0.79, 0], { radius: 0.01 });

  // Centre console: tunnel, armrest, controller, gear selector, wireless charging tray.
  box("center_console", "trim", "interior", [0.82, 0.22, 0.26], [0.12, 0.52, 0], { radius: 0.05 });
  box("center_console", "trim", "interior", [0.32, 0.08, 0.24], [-0.27, 0.665, 0], {
    radius: 0.035,
  });
  add(
    new THREE.CylinderGeometry(0.036, 0.04, 0.035, 28),
    "center_console",
    "chrome",
    "interior",
    (m) => m.position.set(0.0, 0.645, 0),
  );
  box("center_console", "dark", "interior", [0.07, 0.04, 0.05], [0.13, 0.65, 0], { radius: 0.012 });
  box("center_console", "dark", "interior", [0.16, 0.012, 0.1], [0.37, 0.636, 0], {
    radius: 0.004,
  });

  // Sound system: woofers in the doors, tweeters in the dash corners, centre speaker.
  for (const side of SIDES) {
    for (const x of [0.4, -0.8]) {
      add(
        new THREE.CylinderGeometry(0.075, 0.075, 0.03, 28).rotateX(Math.PI / 2),
        "sound_system",
        "dark",
        "interior",
        (m) => m.position.set(x, 0.46, side * 0.86),
      );
    }
    add(
      new THREE.CylinderGeometry(0.03, 0.03, 0.02, 20),
      "sound_system",
      "dark",
      "interior",
      (m) => m.position.set(0.8, 0.965, side * 0.68),
    );
  }
  box("sound_system", "dark", "interior", [0.1, 0.015, 0.22], [0.82, 0.965, 0.25], {
    radius: 0.005,
  });

  // Ambient light strips along the doors and the headliner with its reading lights.
  for (const side of SIDES) {
    box("ambient_light", "glow", "interior", [1.7, 0.01, 0.01], [-0.35, 0.8, side * 0.87], {
      radius: 0.004,
    });
  }
  box("ambient_light", "volume", "interior", [0.9, 0.014, 1.15], [-0.6, 1.42, 0], {
    radius: 0.006,
  });
  box("ambient_light", "glow", "interior", [0.07, 0.016, 0.12], [-0.2, 1.41, 0], {
    radius: 0.006,
  });

  // Driver assistance: the camera module behind the windscreen (radar sits in the grille).
  box("driver_assistance", "dark", "interior", [0.1, 0.06, 0.16], [0.18, 1.28, 0], {
    radius: 0.015,
  });

  // Luggage space as a volume in the boot.
  box("luggage", "volume", "interior", [0.62, 0.42, 1.2], [-1.95, 0.72, 0], { radius: 0.04 });

  root.updateMatrixWorld(true);
  return { root, pieces, sketchLines, anchors: anchorsFor(pieces) };
}

function panelGeometries(grid: ReturnType<typeof buildBodyGrid>) {
  return panelGeometriesOf(grid, bodyPanel, 0);
}
function detailGeometries(grid: ReturnType<typeof buildBodyGrid>) {
  return panelGeometriesOf(grid, bodyDetail, 0.004);
}
import { panelGeometries as panelGeometriesOf } from "./body";

/** A helix along +y (coil spring). */
function helix(radius: number, height: number, turns: number): THREE.Curve<THREE.Vector3> {
  return new (class extends THREE.Curve<THREE.Vector3> {
    override getPoint(t: number, target = new THREE.Vector3()) {
      const a = t * turns * Math.PI * 2;
      return target.set(Math.cos(a) * radius, t * height, Math.sin(a) * radius);
    }
  })();
}

/** Merges a group's (non-indexed) child geometries into one, in the group's space. */
function mergeChildren(group: THREE.Group): THREE.BufferGeometry {
  const positions: number[] = [];
  const normals: number[] = [];
  group.traverse((o) => {
    if (!(o instanceof THREE.Mesh)) return;
    const g = (o.geometry as THREE.BufferGeometry).toNonIndexed();
    g.applyMatrix4(o.matrixWorld);
    positions.push(...(g.getAttribute("position").array as Float32Array));
    normals.push(...(g.getAttribute("normal").array as Float32Array));
  });
  const merged = new THREE.BufferGeometry();
  merged.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  merged.setAttribute("normal", new THREE.Float32BufferAttribute(normals, 3));
  return merged;
}

/** Badge positions where the default view (front left) sees them. */
const ANCHOR_OVERRIDES: Record<string, [number, number, number]> = {
  wheels: [G60.frontAxleX, G60.tyreRadius, -1.0],
  brakes: [G60.rearAxleX - 0.12, G60.tyreRadius + 0.1, -0.95],
  suspension: [G60.frontAxleX, 0.72, -0.62],
  front_doors: [0.35, 0.7, -0.97],
  rear_doors: [-0.75, 0.7, -0.97],
  door_handles: [-0.1, 0.93, -0.97],
  side_windows: [0.05, 1.18, -0.82],
  mirrors: [0.7, 1.1, -1.08],
  headlights: [2.25, 0.8, -0.65],
  taillights: [-2.3, 1.0, -0.7],
  front_seats: [-0.2, 0.9, DRIVER_Z],
  rear_seats: [-1.15, 0.9, -0.45],
  sound_system: [0.4, 0.46, -0.9],
  ambient_light: [-0.35, 0.8, -0.88],
  body: [-1.75, 0.75, -0.97],
  roof: [-0.55, 1.52, 0],
  kidney_grille: [2.45, 0.63, 0],
  front_bumper: [2.35, 0.36, -0.5],
  rear_bumper: [-2.45, 0.6, -0.5],
  drivetrain: [0.4, 0.26, -0.72],
  luggage: [-1.95, 0.95, 0],
};

function anchorsFor(pieces: CarPiece[]): Map<string, THREE.Vector3> {
  const boxes = new Map<string, THREE.Box3>();
  for (const { mesh, partId } of pieces) {
    if (!partId) continue;
    const b = new THREE.Box3().setFromObject(mesh);
    const prev = boxes.get(partId);
    boxes.set(partId, prev ? prev.union(b) : b);
  }
  const anchors = new Map<string, THREE.Vector3>();
  for (const [partId, b] of boxes) {
    const o = ANCHOR_OVERRIDES[partId];
    anchors.set(partId, o ? new THREE.Vector3(...o) : b.getCenter(new THREE.Vector3()));
  }
  return anchors;
}

