import * as THREE from "three";
import type { CarPiece, PieceKind } from "./buildCar";

/**
 * The sketch look: light clay surfaces with ink outlines and panel lines, like a designer's
 * marker rendering. Colours come from the app's CSS tokens, so it follows light and dark mode.
 */

export interface SketchPalette {
  background: THREE.Color;
  ink: THREE.Color;
  muted: THREE.Color;
  brand: THREE.Color;
  mLight: THREE.Color;
  mDark: THREE.Color;
  mRed: THREE.Color;
  dark: boolean;
}

export function readPalette(): SketchPalette {
  const css = getComputedStyle(document.documentElement);
  const token = (name: string, fallback: string) =>
    new THREE.Color(css.getPropertyValue(name).trim() || fallback);
  return {
    background: token("--color-panel", "#ffffff"),
    ink: token("--color-ink", "#111214"),
    muted: token("--color-muted", "#5d636b"),
    brand: token("--color-brand", "#16588e"),
    mLight: token("--color-m-light", "#81c4ff"),
    mDark: token("--color-m-dark", "#16588e"),
    mRed: token("--color-m-red", "#e7222e"),
    dark: document.documentElement.dataset.theme === "dark",
  };
}

/** Base fill per kind; `basic` = unlit (lights, screens, volumes). */
function kindLook(kind: PieceKind, p: SketchPalette): { color: THREE.Color; opacity: number; basic: boolean } {
  const c = (light: string, dark: string) => new THREE.Color(p.dark ? dark : light);
  switch (kind) {
    case "paint":
      return { color: c("#f3f4f5", "#25282c"), opacity: 1, basic: false };
    case "glass":
      return { color: p.mLight.clone(), opacity: p.dark ? 0.16 : 0.22, basic: true };
    case "dark":
      return { color: c("#2b2e33", "#0b0c0e"), opacity: 1, basic: false };
    case "chrome":
      return { color: c("#c3c9d0", "#8d949c"), opacity: 1, basic: false };
    case "lamp":
      return { color: c("#eaf5ff", "#cfe7ff"), opacity: 1, basic: true };
    case "tail":
      return { color: p.mRed.clone(), opacity: 0.9, basic: true };
    case "tyre":
      return { color: c("#33363b", "#0e0f11"), opacity: 1, basic: false };
    case "rim":
      return { color: c("#d9dde2", "#5b6168"), opacity: 1, basic: false };
    case "metal":
      return { color: c("#a3aab2", "#5d636b"), opacity: 1, basic: false };
    case "accent":
      return { color: p.mDark.clone(), opacity: 1, basic: false };
    case "trim":
      return { color: c("#e2e5e8", "#2f3338"), opacity: 1, basic: false };
    case "seat":
      return { color: c("#d3d7dc", "#3a3f46"), opacity: 1, basic: false };
    case "screen":
      return { color: new THREE.Color("#ffffff"), opacity: 1, basic: true };
    case "glow":
      return { color: p.mLight.clone(), opacity: 0.95, basic: true };
    case "volume":
      return { color: p.mLight.clone(), opacity: 0.14, basic: true };
    case "liner":
      return { color: c("#3c4046", "#08090a"), opacity: 1, basic: false };
  }
}

/** Kinds that get an ink silhouette (inverted hull). Thin and see-through ones don't. */
export const OUTLINED: ReadonlySet<PieceKind> = new Set([
  "paint",
  "dark",
  "chrome",
  "tyre",
  "rim",
  "metal",
  "accent",
  "trim",
  "seat",
]);

export type PartState = "idle" | "hasRequirements" | "hover" | "selected";

export interface PieceStyle {
  fill: THREE.MeshLambertMaterial | THREE.MeshBasicMaterial;
  lines: THREE.LineBasicMaterial;
}

export function createPieceStyle(piece: CarPiece, p: SketchPalette, screen: THREE.Texture | null): PieceStyle {
  const look = kindLook(piece.kind, p);
  const common = {
    color: look.color,
    transparent: look.opacity < 1,
    opacity: look.opacity,
    side: THREE.DoubleSide,
    depthWrite: look.opacity >= 1,
    polygonOffset: true,
    polygonOffsetFactor: 1,
    polygonOffsetUnits: 1,
  } as const;
  const fill = look.basic
    ? new THREE.MeshBasicMaterial({ ...common, map: piece.kind === "screen" ? screen : null })
    : new THREE.MeshLambertMaterial(common);
  fill.userData.base = { color: look.color.clone(), opacity: look.opacity };
  const lines = new THREE.LineBasicMaterial({ color: p.ink, transparent: true, opacity: 0.6 });
  return { fill, lines };
}

/** Applies the part state and view mode to one piece. Returns whether it can be clicked. */
export function applyState(
  piece: CarPiece,
  style: PieceStyle,
  state: PartState,
  ghost: boolean,
  p: SketchPalette,
): boolean {
  const base = style.fill.userData.base as { color: THREE.Color; opacity: number };
  const color = base.color.clone();
  let opacity = base.opacity;
  let lineColor = p.ink;
  let lineOpacity = piece.layer === "interior" ? 0.45 : 0.62;
  const tintable = piece.kind !== "screen" && piece.kind !== "tail" && piece.kind !== "glow";
  if (state === "hasRequirements" && tintable) color.lerp(p.mLight, 0.35);
  if (state === "hover") {
    if (tintable) color.lerp(p.brand, 0.25);
    lineColor = p.brand;
    lineOpacity = 1;
  }
  if (state === "selected") {
    if (tintable) color.lerp(p.brand, 0.5);
    lineColor = p.brand;
    lineOpacity = 1;
    if (piece.kind === "glass" || piece.kind === "volume") opacity = Math.max(opacity, 0.45);
  }
  if (ghost) {
    opacity = state === "selected" || state === "hover" ? 0.18 : 0.035;
    lineOpacity = state === "selected" || state === "hover" ? 0.7 : 0.16;
  }
  style.fill.color.copy(color);
  style.fill.opacity = opacity;
  style.fill.transparent = opacity < 1;
  style.fill.depthWrite = opacity >= 1;
  style.fill.needsUpdate = true;
  style.lines.color.copy(lineColor);
  style.lines.opacity = lineOpacity;
  return !ghost && piece.partId !== null;
}

/** Ink silhouette: back faces pushed out by a constant number of pixels. */
export function createOutlineMaterial(color: THREE.Color, widthPx: number): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    side: THREE.BackSide,
    uniforms: {
      color: { value: color.clone() },
      width: { value: widthPx },
      resolution: { value: new THREE.Vector2(1, 1) },
    },
    vertexShader: /* glsl */ `
      uniform float width;
      uniform vec2 resolution;
      void main() {
        vec4 clip = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        vec3 n = normalize(normalMatrix * normal);
        vec4 clipN = projectionMatrix * vec4(n, 0.0);
        vec2 dir = length(clipN.xy) > 1e-5 ? normalize(clipN.xy) : vec2(0.0);
        clip.xy += dir * width * 2.0 / resolution * clip.w;
        gl_Position = clip;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 color;
      void main() { gl_FragColor = vec4(color, 1.0); }
    `,
  });
}

/** The curved display's content, drawn like a sketch: cluster gauges on the left, a map on the right. */
export function drawScreen(p: SketchPalette): THREE.CanvasTexture {
  const canvas = document.createElement("canvas");
  canvas.width = 1024;
  canvas.height = 144;
  const ctx = canvas.getContext("2d")!;
  const bg = p.dark ? "#0b0d10" : "#1a1d22";
  const line = "#81c4ff";
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = line;
  ctx.fillStyle = line;
  ctx.lineWidth = 3;
  // Driver display: two dials and a speed readout.
  for (const cx of [90, 330]) {
    ctx.globalAlpha = 0.85;
    ctx.beginPath();
    ctx.arc(cx, 92, 58, Math.PI * 0.85, Math.PI * 2.15);
    ctx.stroke();
    ctx.globalAlpha = 0.4;
    ctx.beginPath();
    ctx.arc(cx, 92, 46, Math.PI * 0.85, Math.PI * 1.6);
    ctx.stroke();
  }
  ctx.globalAlpha = 0.95;
  ctx.font = "600 44px -apple-system, system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("48", 210, 92);
  ctx.font = "500 16px -apple-system, system-ui, sans-serif";
  ctx.globalAlpha = 0.6;
  ctx.fillText("km/h", 210, 116);
  // Divider, then the central display: a map with a route and app tiles.
  ctx.globalAlpha = 0.3;
  ctx.fillRect(452, 18, 2, 108);
  ctx.globalAlpha = 0.18;
  ctx.lineWidth = 2;
  for (let x = 480; x < 860; x += 34) {
    ctx.beginPath();
    ctx.moveTo(x, 12);
    ctx.lineTo(x + 40, 132);
    ctx.stroke();
  }
  for (let y = 22; y < 140; y += 30) {
    ctx.beginPath();
    ctx.moveTo(470, y);
    ctx.lineTo(870, y + 10);
    ctx.stroke();
  }
  ctx.globalAlpha = 0.95;
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(520, 128);
  ctx.bezierCurveTo(600, 90, 640, 110, 700, 60);
  ctx.lineTo(820, 30);
  ctx.stroke();
  ctx.lineWidth = 2;
  ctx.globalAlpha = 0.7;
  for (let i = 0; i < 3; i++) {
    ctx.strokeRect(890, 16 + i * 40, 110, 30);
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  // The display is seen from inside its cylinder: mirror so the cluster sits behind the wheel.
  tex.wrapS = THREE.RepeatWrapping;
  tex.repeat.x = -1;
  return tex;
}

/** Soft contact shadow under the car. */
export function shadowTexture(): THREE.CanvasTexture {
  const canvas = document.createElement("canvas");
  canvas.width = 256;
  canvas.height = 128;
  const ctx = canvas.getContext("2d")!;
  const g = ctx.createRadialGradient(128, 64, 8, 128, 64, 128);
  g.addColorStop(0, "rgba(0,0,0,0.55)");
  g.addColorStop(0.55, "rgba(0,0,0,0.25)");
  g.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 256, 128);
  return new THREE.CanvasTexture(canvas);
}

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";
import { cx } from "@/lib/cx";
import { label } from "./classify";
import { buildCar, type CarPiece } from "./model/buildCar";
import {
  applyState,
  createOutlineMaterial,
  createPieceStyle,
  drawScreen,
  OUTLINED,
  readPalette,
  shadowTexture,
  type PartState,
  type PieceStyle,
  type SketchPalette,
} from "./model/sketch";

export type CarView = "exterior" | "interior";
export type CameraPreset = "front" | "side" | "rear" | "top";

const PRESETS: Record<CameraPreset, { position: [number, number, number]; target: [number, number, number] }> = {
  front: { position: [5.0, 2.1, -5.2], target: [0, 0.68, 0] },
  side: { position: [0, 1.1, -7.6], target: [0, 0.7, 0] },
  rear: { position: [-5.2, 2.3, -4.6], target: [0, 0.68, 0] },
  top: { position: [0.01, 8.4, -0.4], target: [0, 0.5, 0] },
};

const UNGHOSTED_KINDS = new Set(["tyre", "rim", "metal", "accent"]);

interface Props {
  /** Requirements per part id (only parts with ≥ 1 are badged and tinted). */
  counts: ReadonlyMap<string, number>;
  selected: string | null;
  view: CarView;
  preset: CameraPreset;
  /** Bumped to move the camera to `preset` again. */
  presetNonce: number;
  onSelect: (partId: string | null) => void;
}

/**
 * The 3D car: drag to orbit, scroll to zoom, right-drag to pan. Hover shows the part's name, a click
 * selects it. Parts with requirements carry a badge with the count; badges are clickable too.
 */
export function CarViewer(props: Props) {
  const hostRef = useRef<HTMLDivElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);
  const badgeRefs = useRef(new Map<string, HTMLButtonElement>());
  const propsRef = useRef(props);
  propsRef.current = props;
  const apiRef = useRef<{ restyle: () => void; moveTo: (p: CameraPreset) => void } | null>(null);
  const [hovered, setHovered] = useState<string | null>(null);
  const [failed, setFailed] = useState<string | null>(null);
  const [anchors, setAnchors] = useState<ReadonlyMap<string, THREE.Vector3>>(new Map());

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;

    let renderer: THREE.WebGLRenderer;
    try {
      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    } catch (e) {
      setFailed(e instanceof Error ? e.message : "WebGL is not available");
      return;
    }
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.domElement.dataset.testid = "car-canvas";
    renderer.domElement.style.display = "block";
    host.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(32, 1, 0.05, 100);
    camera.position.set(...PRESETS.front.position);
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.target.set(...PRESETS.front.target);
    controls.enableDamping = true;
    controls.dampingFactor = 0.08;
    controls.minDistance = 2.2;
    controls.maxDistance = 16;
    controls.maxPolarAngle = Math.PI * 0.495;
    controls.update();

    scene.add(new THREE.HemisphereLight(0xffffff, 0x8a8f96, 2.4));
    const sun = new THREE.DirectionalLight(0xffffff, 1.6);
    sun.position.set(3, 6, -4);
    scene.add(sun);
    const fill = new THREE.DirectionalLight(0xffffff, 0.5);
    fill.position.set(-4, 2, 5);
    scene.add(fill);

    const car = buildCar();
    scene.add(car.root);
    setAnchors(car.anchors);

    // Ground: a soft contact shadow and a faint drafting grid.
    const shadowTex = shadowTexture();
    const shadow = new THREE.Mesh(
      new THREE.PlaneGeometry(6.2, 2.9),
      new THREE.MeshBasicMaterial({ map: shadowTex, transparent: true, depthWrite: false }),
    );
    shadow.rotation.x = -Math.PI / 2;
    shadow.position.y = 0.002;
    scene.add(shadow);
    const grid = new THREE.GridHelper(14, 28);
    const gridMat = grid.material as THREE.LineBasicMaterial;
    gridMat.transparent = true;
    scene.add(grid);

    let palette: SketchPalette = readPalette();
    let screenTex = drawScreen(palette);
    const outline = createOutlineMaterial(palette.ink, 1.4);
    const styles = new Map<CarPiece, PieceStyle>();
    const outlines = new Map<CarPiece, THREE.Mesh>();
    const pickable: THREE.Mesh[] = [];

    for (const piece of car.pieces) {
      const style = createPieceStyle(piece, palette, screenTex);
      piece.mesh.material = style.fill;
      styles.set(piece, style);
      const threshold = piece.kind === "paint" || piece.kind === "glass" ? 32 : 40;
      const edges = new THREE.LineSegments(new THREE.EdgesGeometry(piece.mesh.geometry, threshold), style.lines);
      edges.raycast = () => {};
      piece.mesh.add(edges);
      if (OUTLINED.has(piece.kind)) {
        const hull = new THREE.Mesh(piece.mesh.geometry, outline);
        hull.raycast = () => {};
        piece.mesh.add(hull);
        outlines.set(piece, hull);
      }
    }
    const sketchMat = new THREE.LineBasicMaterial({ color: palette.ink, transparent: true, opacity: 0.35 });
    for (const geo of car.sketchLines) scene.add(new THREE.LineSegments(geo, sketchMat));

    let hoveredPart: string | null = null;
    let dirty = true;

    const restyle = () => {
      const { counts, selected, view } = propsRef.current;
      scene.background = palette.background;
      gridMat.color.copy(palette.muted);
      gridMat.opacity = palette.dark ? 0.16 : 0.12;
      (shadow.material as THREE.MeshBasicMaterial).opacity = palette.dark ? 0.9 : 0.55;
      outline.uniforms.color!.value.copy(palette.ink);
      sketchMat.color.copy(palette.ink);
      sketchMat.opacity = view === "interior" ? 0.08 : 0.35;
      pickable.length = 0;
      for (const piece of car.pieces) {
        const state: PartState =
          piece.partId && piece.partId === selected
            ? "selected"
            : piece.partId && piece.partId === hoveredPart
              ? "hover"
              : piece.partId && (counts.get(piece.partId) ?? 0) > 0
                ? "hasRequirements"
                : "idle";
        const ghost =
          view === "interior" && piece.layer === "exterior" && !UNGHOSTED_KINDS.has(piece.kind);
        const canPick = applyState(piece, styles.get(piece)!, state, ghost, palette);
        const hull = outlines.get(piece);
        if (hull) hull.visible = !ghost;
        if (canPick) pickable.push(piece.mesh);
      }
      dirty = true;
    };

    const onTheme = new MutationObserver(() => {
      palette = readPalette();
      const old = screenTex;
      screenTex = drawScreen(palette);
      for (const piece of car.pieces) {
        const style = createPieceStyle(piece, palette, screenTex);
        const current = styles.get(piece)!;
        current.fill.userData.base = style.fill.userData.base;
        if (current.fill instanceof THREE.MeshBasicMaterial && piece.kind === "screen") {
          current.fill.map = screenTex;
        }
        style.fill.dispose();
        style.lines.dispose();
      }
      old.dispose();
      restyle();
    });
    onTheme.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });

    // Camera moves between presets.
    let flight: { from: THREE.Vector3; to: THREE.Vector3; fromT: THREE.Vector3; toT: THREE.Vector3; t0: number } | null =
      null;
    const moveTo = (preset: CameraPreset) => {
      const p = PRESETS[preset];
      flight = {
        from: camera.position.clone(),
        to: new THREE.Vector3(...p.position),
        fromT: controls.target.clone(),
        toT: new THREE.Vector3(...p.target),
        t0: performance.now(),
      };
    };
    apiRef.current = { restyle, moveTo };

    // Picking.
    const raycaster = new THREE.Raycaster();
    const pointer = new THREE.Vector2();
    let pointerInside = false;
    let pointerPx = { x: 0, y: 0 };
    let needsPick = false;
    const pick = (): string | null => {
      raycaster.setFromCamera(pointer, camera);
      const hit = raycaster.intersectObjects(pickable, false)[0];
      return (hit?.object.userData.partId as string | null | undefined) ?? null;
    };
    const setPointer = (e: PointerEvent) => {
      const r = renderer.domElement.getBoundingClientRect();
      pointerPx = { x: e.clientX - r.left, y: e.clientY - r.top };
      pointer.set((pointerPx.x / r.width) * 2 - 1, -(pointerPx.y / r.height) * 2 + 1);
    };
    let down: { x: number; y: number } | null = null;
    const onMove = (e: PointerEvent) => {
      setPointer(e);
      pointerInside = true;
      needsPick = true;
    };
    const onLeave = () => {
      pointerInside = false;
      needsPick = true;
    };
    const onDown = (e: PointerEvent) => {
      down = { x: e.clientX, y: e.clientY };
    };
    const onUp = (e: PointerEvent) => {
      if (!down || e.button !== 0) return;
      const moved = Math.hypot(e.clientX - down.x, e.clientY - down.y);
      down = null;
      if (moved > 5) return;
      setPointer(e);
      propsRef.current.onSelect(pick());
    };
    const el = renderer.domElement;
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);
    el.addEventListener("pointerdown", onDown);
    el.addEventListener("pointerup", onUp);

    const resize = () => {
      const { clientWidth: w, clientHeight: h } = host;
      if (w === 0 || h === 0) return;
      renderer.setSize(w, h, false);
      renderer.domElement.style.width = `${w}px`;
      renderer.domElement.style.height = `${h}px`;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      const size = renderer.getDrawingBufferSize(new THREE.Vector2());
      outline.uniforms.resolution!.value.copy(size);
      outline.uniforms.width!.value = 1.4 * renderer.getPixelRatio();
      dirty = true;
    };
    const ro = new ResizeObserver(resize);
    ro.observe(host);
    resize();
    restyle();

    // Render loop: only draws when something changed.
    const v = new THREE.Vector3();
    let frame = 0;
    const loop = () => {
      frame = requestAnimationFrame(loop);
      if (flight) {
        const t = Math.min(1, (performance.now() - flight.t0) / 650);
        const e = t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2;
        camera.position.lerpVectors(flight.from, flight.to, e);
        controls.target.lerpVectors(flight.fromT, flight.toT, e);
        if (t >= 1) flight = null;
        dirty = true;
      }
      if (controls.update()) dirty = true;
      if (needsPick) {
        needsPick = false;
        const part = pointerInside ? pick() : null;
        if (part !== hoveredPart) {
          hoveredPart = part;
          setHovered(part);
          el.style.cursor = part ? "pointer" : "grab";
          restyle();
        }
      }
      const tip = tooltipRef.current;
      if (tip) tip.style.transform = `translate(${pointerPx.x + 14}px, ${pointerPx.y + 12}px)`;
      if (!dirty) return;
      dirty = false;
      renderer.render(scene, camera);
      // Badges follow their anchors.
      const { clientWidth: w, clientHeight: h } = host;
      for (const [partId, badge] of badgeRefs.current) {
        const anchor = car.anchors.get(partId);
        if (!anchor) continue;
        v.copy(anchor).project(camera);
        const visible = v.z < 1 && Math.abs(v.x) < 1.05 && Math.abs(v.y) < 1.05;
        badge.style.visibility = visible ? "visible" : "hidden";
        badge.style.transform = `translate(${((v.x + 1) / 2) * w}px, ${((1 - v.y) / 2) * h}px) translate(-50%, -50%)`;
      }
    };
    loop();

    return () => {
      cancelAnimationFrame(frame);
      ro.disconnect();
      onTheme.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      el.removeEventListener("pointerdown", onDown);
      el.removeEventListener("pointerup", onUp);
      controls.dispose();
      scene.traverse((o) => {
        if (o instanceof THREE.Mesh || o instanceof THREE.LineSegments) o.geometry.dispose();
      });
      for (const s of styles.values()) {
        s.fill.dispose();
        s.lines.dispose();
      }
      outline.dispose();
      sketchMat.dispose();
      screenTex.dispose();
      shadowTex.dispose();
      renderer.dispose();
      renderer.domElement.remove();
      apiRef.current = null;
    };
  }, []);

  // React to selection, counts and view changes without rebuilding the scene.
  useEffect(() => {
    apiRef.current?.restyle();
  }, [props.counts, props.selected, props.view]);

  useEffect(() => {
    apiRef.current?.moveTo(props.preset);
  }, [props.preset, props.presetNonce]);

  if (failed) {
    return (
      <div className="grid h-full place-items-center p-8 text-center text-sm text-muted">
        <p>
          The 3D car needs WebGL, which isn't available here ({failed}). Pick a part from the list
          instead.
        </p>
      </div>
    );
  }

  const badged = [...props.counts.entries()].filter(([id, n]) => n > 0 && anchors.has(id));
  return (
    <div ref={hostRef} className="relative h-full w-full overflow-hidden" data-testid="car-viewer">
      {badged.map(([partId, n]) => (
        <button
          key={partId}
          type="button"
          ref={(el) => {
            if (el) badgeRefs.current.set(partId, el);
            else badgeRefs.current.delete(partId);
          }}
          onClick={() => props.onSelect(partId)}
          data-testid={`car-badge-${partId}`}
          title={`${label(partId)}: ${n} requirement${n === 1 ? "" : "s"}`}
          className={cx(
            "absolute top-0 left-0 grid h-6 min-w-6 place-items-center rounded-full border px-1.5 text-xs font-semibold shadow-sm transition-colors",
            props.selected === partId
              ? "border-brand bg-brand-fill text-white"
              : "border-line bg-panel text-ink hover:border-brand",
          )}
          style={{ visibility: "hidden" }}
        >
          {n}
        </button>
      ))}
      <div
        ref={tooltipRef}
        className={cx(
          "pointer-events-none absolute top-0 left-0 rounded-md border border-line bg-panel px-2 py-1 text-xs font-medium text-ink shadow-sm",
          hovered ? "opacity-100" : "opacity-0",
        )}
      >
        {hovered ? label(hovered) : ""}
      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from "react";
import type { Requirement } from "@reqflow/core";
import { fixtureRequirements } from "@reqflow/core/fixtures";
import { api, ReqflowError } from "@/lib/api";
import { groupByPart, type ClassifiedRequirement } from "./classify";

export type RequirementSource = "app" | "sample";

/**
 * The requirements shown on the car: what Add to Car produced (`requirements.list`), reloaded
 * whenever a run changes, or the synthetic fixtures when the user asks for the sample explicitly.
 */
export function useCarRequirements(source: RequirementSource) {
  const [loaded, setLoaded] = useState<Requirement[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  const reload = useCallback(async () => {
    try {
      setLoaded(await api.requirements.list());
      setError(null);
    } catch (e) {
      setLoaded([]);
      setError(
        e instanceof ReqflowError && e.code === "not_implemented"
          ? "The requirement store isn't available in this build yet."
          : e instanceof Error
            ? e.message
            : String(e),
      );
    }
  }, []);

  useEffect(() => {
    void reload();
    return api.runs.onUpdate(() => void reload());
  }, [reload]);

  const requirements = source === "sample" ? fixtureRequirements : (loaded ?? []);
  const byPart = useMemo(() => groupByPart(requirements), [requirements]);
  const counts = useMemo(
    () => new Map([...byPart.entries()].map(([id, list]) => [id, list.length])),
    [byPart],
  );
  return {
    loading: source === "app" && loaded === null,
    error: source === "app" ? error : null,
    total: requirements.length,
    byPart: byPart as ReadonlyMap<string, ClassifiedRequirement[]>,
    counts: counts as ReadonlyMap<string, number>,
  };
}

import { CATEGORY_LABELS, type Priority } from "@reqflow/core";
import { cx } from "@/lib/cx";
import { XIcon } from "@/components/ui/icons";
import { label, type ClassifiedRequirement, type Confidence } from "./classify";
import { CAR_PARTS, PART_GROUP_LABELS, PARTS_BY_ID, WHOLE_CAR, type PartGroup } from "./parts";

const PRIORITY_LABELS: Record<Priority, string> = {
  must: "Must",
  should: "Should",
  could: "Could",
  wont: "Won't",
};
const CONFIDENCE_LABELS: Record<Confidence, string> = {
  high: "high confidence",
  medium: "medium confidence",
  low: "low confidence — check it",
};
const STATUS_LABELS: Record<string, string> = {
  proposed: "Proposed",
  in_review: "In review",
  challenged: "Challenged",
  approved: "Approved",
  rejected: "Rejected",
  deferred: "Deferred",
};

interface Props {
  selected: string | null;
  byPart: ReadonlyMap<string, ClassifiedRequirement[]>;
  counts: ReadonlyMap<string, number>;
  total: number;
  emptyHint: string;
  onSelect: (partId: string | null) => void;
}

/** Right-hand side of the Car tab: the selected part and its requirements, or the part index. */
export function PartPanel(props: Props) {
  if (props.selected) return <PartDetail {...props} partId={props.selected} />;
  return <PartIndex {...props} />;
}

function PartIndex({ counts, total, emptyHint, onSelect }: Props) {
  const groups: PartGroup[] = ["exterior", "interior", "technology"];
  const whole = counts.get(WHOLE_CAR.id) ?? 0;
  return (
    <div className="flex h-full flex-col" data-testid="car-part-index">
      <div className="border-b border-line px-4 pt-1 pb-3 text-sm text-muted">
        {total === 0 ? (
          emptyHint
        ) : (
          <>
            <span className="font-medium text-ink">{total}</span> requirement{total === 1 ? "" : "s"}{" "}
            on the car. Click a part, a badge or a row below.
          </>
        )}
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto px-2 py-2">
        <PartRow id={WHOLE_CAR.id} name={WHOLE_CAR.label} count={whole} onSelect={onSelect} />
        {groups.map((g) => (
          <div key={g} className="mt-3">
            <h3 className="px-2 pb-1 text-[11px] font-semibold tracking-wide text-muted uppercase">
              {PART_GROUP_LABELS[g]}
            </h3>
            {CAR_PARTS.filter((p) => p.group === g).map((p) => (
              <PartRow key={p.id} id={p.id} name={p.label} count={counts.get(p.id) ?? 0} onSelect={onSelect} />
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}

function PartRow(props: { id: string; name: string; count: number; onSelect: (id: string) => void }) {
  return (
    <button
      type="button"
      onClick={() => props.onSelect(props.id)}
      data-testid={`car-part-${props.id}`}
      className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm hover:bg-panel-2"
    >
      <span className={cx("min-w-0 flex-1 truncate", props.count === 0 && "text-muted")}>{props.name}</span>
      {props.count > 0 && (
        <span className="grid h-5 min-w-5 place-items-center rounded-full bg-brand-soft px-1.5 text-xs font-semibold text-brand">
          {props.count}
        </span>
      )}
    </button>
  );
}

function PartDetail({ partId, byPart, emptyHint, onSelect }: Props & { partId: string }) {
  const part = PARTS_BY_ID.get(partId);
  const items = byPart.get(partId) ?? [];
  return (
    <div className="flex h-full flex-col" data-testid="car-part-detail">
      <div className="flex items-start gap-2 border-b border-line px-4 pt-1 pb-3">
        <div className="min-w-0 flex-1">
          <p className="text-[11px] font-semibold tracking-wide text-muted uppercase">
            {part ? PART_GROUP_LABELS[part.group] : "Overall"}
          </p>
          <h3 className="text-base font-medium text-ink" data-testid="car-part-title">
            {label(partId)}
          </h3>
          <p className="mt-1 text-sm text-muted">{part?.blurb ?? WHOLE_CAR.blurb}</p>
        </div>
        <button
          type="button"
          aria-label="Back to all parts"
          onClick={() => onSelect(null)}
          className="rounded-md p-1 text-muted hover:bg-panel-2 hover:text-ink"
        >
          <XIcon className="size-4" />
        </button>
      </div>
      <div className="min-h-0 flex-1 space-y-2 overflow-y-auto p-3" data-testid="car-part-requirements">
        {items.length === 0 ? (
          <p className="px-1 py-6 text-center text-sm text-muted">
            No requirements from Add to Car on this part yet.
            <br />
            <span className="text-xs">{emptyHint}</span>
          </p>
        ) : (
          items.map((item) => <RequirementCard key={item.requirement.id} item={item} />)
        )}
      </div>
    </div>
  );
}

function RequirementCard({ item }: { item: ClassifiedRequirement }) {
  const { requirement: r, assignment: a } = item;
  return (
    <article className="rounded-lg border border-line bg-panel p-3" data-testid="car-requirement">
      <div className="flex items-center gap-2 text-xs text-muted">
        <span className="font-mono">{r.id}</span>
        <span className="ml-auto">{STATUS_LABELS[r.status] ?? r.status}</span>
      </div>
      <h4 className="mt-1 text-sm font-medium text-ink">{r.title}</h4>
      <p className="mt-1 text-sm text-muted">{r.description}</p>
      <div className="mt-2 flex flex-wrap items-center gap-1.5 text-xs">
        {r.priority && (
          <Chip strong={r.priority === "must"}>
            {PRIORITY_LABELS[r.priority]}
            {r.score ? ` · ${Math.round(r.score.total)}` : ""}
          </Chip>
        )}
        <Chip warn={r.evidenceLevel === "D" && (r.priority === "must" || r.priority === "should")}>
          Evidence {r.evidenceLevel}
        </Chip>
        <Chip>{CATEGORY_LABELS[r.category]}</Chip>
      </div>
      {r.targets.length > 0 && (
        <ul className="mt-2 space-y-0.5 text-xs text-muted">
          {r.targets.map((t) => (
            <li key={t.metric}>
              <span className="text-ink">{t.metric}:</span> {t.target}
            </li>
          ))}
        </ul>
      )}
      <p className="mt-2 border-t border-line pt-2 text-xs text-muted" data-testid="car-classifier-reason">
        <span className="font-medium text-ink">Auto-classified</span> ({CONFIDENCE_LABELS[a.confidence]}):{" "}
        {a.reason}
        {a.alternatives.length > 0 && (
          <> Could also be: {a.alternatives.map((x) => label(x.partId)).join(", ")}.</>
        )}
      </p>
    </article>
  );
}

function Chip(props: { children: React.ReactNode; strong?: boolean; warn?: boolean }) {
  return (
    <span
      className={cx(
        "rounded-full border px-2 py-0.5",
        props.strong
          ? "border-transparent bg-brand-fill text-white"
          : props.warn
            ? "border-transparent bg-warn-soft text-warn"
            : "border-line text-muted",
      )}
    >
      {props.children}
    </span>
  );
}

