import { useState } from "react";
import { CarViewer, type CameraPreset, type CarView } from "@/components/car/CarViewer";
import { PartPanel } from "@/components/car/PartPanel";
import { useCarRequirements, type RequirementSource } from "@/components/car/useCarRequirements";
import { Segmented } from "@/components/settings/Segmented";
import { Button } from "@/components/ui/Button";
import { MStripe } from "@/components/ui/MStripe";
import { Panel } from "@/components/ui/Panel";
import { useSettings } from "@/lib/settings";

const VIEWS = [
  { value: "exterior", label: "Exterior" },
  { value: "interior", label: "Interior" },
] as const;
const SOURCES = [
  { value: "app", label: "From Add to Car" },
  { value: "sample", label: "Synthetic sample" },
] as const;
const PRESETS: { value: CameraPreset; label: string }[] = [
  { value: "front", label: "Front" },
  { value: "side", label: "Side" },
  { value: "rear", label: "Rear" },
  { value: "top", label: "Top" },
];

/**
 * The car: a 3D sketch of the vehicle where every part can be clicked to see the requirements on
 * it. The auto classifier decides which part a requirement belongs to; it never changes the
 * requirement itself.
 */
export function CarPage() {
  const scope = useSettings((s) => s.settings.defaultScope);
  const [view, setView] = useState<CarView>("exterior");
  const [source, setSource] = useState<RequirementSource>("app");
  const [selected, setSelected] = useState<string | null>(null);
  const [preset, setPreset] = useState<CameraPreset>("front");
  const [presetNonce, setPresetNonce] = useState(0);
  const data = useCarRequirements(source);

  const emptyHint =
    data.error ??
    (data.loading
      ? "Loading requirements…"
      : source === "app"
        ? "Run a flow with an Add to Car block, or switch to the synthetic sample to try it."
        : "");

  return (
    <div className="flex h-full gap-2">
      <h1 className="sr-only">Car</h1>
      <Panel
        title={
          <span className="flex items-center gap-2.5">
            <MStripe variant="badge" />
            BMW {scope.vehicleLine}
            {scope.derivative ? ` ${scope.derivative}` : ""}
            <span className="text-sm font-normal text-muted">
              {scope.market} · {scope.horizonYears}-year horizon
            </span>
          </span>
        }
        actions={
          <>
            <Segmented options={VIEWS} value={view} onChange={setView} testIdPrefix="car-view-" />
            <div className="flex items-center gap-1">
              {PRESETS.map((p) => (
                <Button
                  key={p.value}
                  size="sm"
                  variant={preset === p.value ? "secondary" : "ghost"}
                  data-testid={`car-camera-${p.value}`}
                  onClick={() => {
                    setPreset(p.value);
                    setPresetNonce((n) => n + 1);
                  }}
                >
                  {p.label}
                </Button>
              ))}
            </div>
          </>
        }
        className="min-w-0 flex-1"
        testId="car-page"
      >
        <div className="relative h-full">
          <CarViewer
            counts={data.counts}
            selected={selected}
            view={view}
            preset={preset}
            presetNonce={presetNonce}
            onSelect={setSelected}
          />
          <p className="pointer-events-none absolute bottom-3 left-4 text-xs text-muted">
            Sketch modelled on the 5 Series Sedan (G60) dimensions · drag to turn, scroll to zoom,
            click any part
          </p>
        </div>
      </Panel>
      <Panel
        title="Parts & requirements"
        actions={
          <Segmented options={SOURCES} value={source} onChange={setSource} testIdPrefix="car-source-" />
        }
        className="w-[26rem] shrink-0"
        testId="car-side"
      >
        <PartPanel
          selected={selected}
          byPart={data.byPart}
          counts={data.counts}
          total={data.total}
          emptyHint={emptyHint}
          onSelect={setSelected}
        />
      </Panel>
    </div>
  );
}

